let (tx, rx) = std::sync::mpsc::sync_channel::<Job>(1000);  // send blocks when full

// Receiver is not Sync: one consumer thread, or use crossbeam-channel for fan-out.
std::thread::spawn(move || {
    while let Ok(job) = rx.recv() {
        process(job);
    }
});

tx.send(job).unwrap();        // paced: waits for a slot instead of dropping
// tx.try_send(job) -> Err(Full) is the explicit shed path

