let (tx, mut rx) = tokio::sync::mpsc::channel::<Job>(1000);  // send awaits capacity

tokio::spawn(async move {
    while let Some(job) = rx.recv().await {
        tokio::spawn(process(job));     // bound downstream with a semaphore
    }
});

tx.send(job).await.unwrap();            // paced instead of dropped
